<?php

declare(strict_types=1);

namespace VeryCodeCom\FurgonetkaApi\Exception;

/**
 * Thrown on network-level failures: cURL errors, DNS problems, SSL failures, timeouts.
 *
 * When the failure happened while an asynchronous command was being submitted or polled, the
 * command's UUID travels with the exception. The UUID is generated by the client before the
 * request is sent, so it is known even when the request never got an answer, and the caller can
 * come back with `fetchOrderCommand($uuid)` instead of ordering a second time.
 */
class FurgonetkaApiTransportException extends FurgonetkaApiException
{
    private ?string $commandUuid = null;

    /**
     * Record which command this failure belongs to (fluent).
     *
     * @return $this
     */
    public function withCommandUuid(?string $commandUuid): static
    {
        $this->commandUuid = $commandUuid;
        return $this;
    }

    /** UUID of the command that was in flight, or null when the failure is not about a command. */
    public function commandUuid(): ?string
    {
        return $this->commandUuid;
    }
}
